const introCanvas=document.querySelector('canvas'),introCtx=introCanvas.getContext('2d'),introStatus=document.querySelector('#status');
let introIndex=0,introReady=false,introMotion=null,introMotions={},introScale=2;
function introRender(){if(!introReady)return;currentUI.base(introCtx,introIndex?'intro'+(introIndex+1):'title');introMotions[introIndex+1]?.draw(introCtx);introCanvas.setAttribute('aria-label','Заставка '+(introIndex+1));introStatus.textContent='Заставка '+(introIndex+1)+' / 5';['first','second','third','fourth','fifth'].forEach((name,i)=>document.querySelector('#intro-'+name).setAttribute('aria-pressed',String(introIndex===i)));}
const previewClock=PeninsulaScenes.clock();
function introSelect(index){introIndex=Math.max(0,Math.min(4,index));previewClock.select('intro'+(introIndex+1));previewClock.restart();if(introReady){introMotion=introMotions[introIndex+1];introMotion.reset();window.buildParallaxControls(document.querySelector('#parallax-controls'),introMotion,()=>{previewClock.restart();introRender()})}document.querySelector('#parallax-controls').hidden=false;introRender()}
function introResize(){const dpr=window.devicePixelRatio||1,factor=Math.round(introScale*dpr)/dpr;const frame=document.querySelector('#screen');frame.style.width=320*factor+'px';frame.style.height=240*factor+'px';document.querySelectorAll('[data-scale]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.scale)===introScale)))}
document.querySelectorAll('[data-scale]').forEach(b=>b.onclick=()=>{introScale=Number(b.dataset.scale);introResize()});window.addEventListener('resize',introResize);introResize();
['first','second','third','fourth','fifth'].forEach((name,i)=>document.querySelector('#intro-'+name).onclick=()=>introSelect(i));introCanvas.addEventListener('click',()=>introSelect((introIndex+1)%5));window.addEventListener('keydown',e=>{if(e.target?.matches?.('input,select,textarea,button')||e.repeat)return;if(['Enter',' ','ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();introSelect((introIndex+(e.key==='ArrowLeft'?4:1))%5)}});
for(const [key,value]of Object.entries(currentUI.settings))document.querySelector('#'+key).value=value;
function introAppearance(){for(const [key,value]of Object.entries(currentUI.settings)){const input=document.querySelector('#'+key);currentUI.settings[key]=typeof value==='number'?Math.round(Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)||0))):input.value;}try{localStorage.setItem('peninsula-layout-settings',JSON.stringify(currentUI.settings))}catch{}if(introReady){currentUI.tint();introRender()}}
document.querySelectorAll('[data-setting]').forEach(input=>input.addEventListener('input',introAppearance));document.querySelector('#reset').onclick=()=>{const defaults={textColor:'#bec4c9',lineColor:'#91a1ad',headingBackground:'#293640',headingColor:'#bec4c9',lineStep:13,padding:5,resourcePadding:5,narratorOffset:0,resourceOffset:1};for(const [key,value]of Object.entries(defaults))document.querySelector('#'+key).value=value;introAppearance()};
Promise.all([currentUI.ready,...[1,2,3,4,5].map(n=>window.loadIntroParallax(n))]).then(([, ...motions])=>{
 introMotions=Object.fromEntries(motions.map((motion,i)=>[i+1,motion]));introReady=true;introSelect(Number(new URLSearchParams(location.search).get('intro')||1)-1);let last=null;
 function animate(now){const visible=!document.hidden,dt=last===null?0:(now-last)/1000;last=now;for(const [n,motion]of Object.entries(introMotions))motion.tick(now,visible&&introIndex===Number(n)-1);if(previewClock.tick(dt,visible))introSelect((introIndex+1)%5);else introRender();requestAnimationFrame(animate)}
 document.addEventListener('visibilitychange',()=>{last=null;for(const motion of Object.values(introMotions))motion.tick(performance.now(),false)});requestAnimationFrame(animate);
}).catch(e=>{introStatus.textContent='Не удалось загрузить слои заставки. Обновите страницу.';console.error(e)});
